-- HRMS Plaridel complete fresh-install schema
-- Core HR + DTR + L&D + RSP + DocuTracker modules and policies
-- PostgreSQL
-- Run this entire file in pgAdmin Query Tool against an empty database, or:
--   psql -d YOUR_EMPTY_DATABASE -v ON_ERROR_STOP=1 -f scripts/init-schema.sql
--
-- Fresh databases only. All required definitions are included in this file.
-- Existing databases use targeted scripts under scripts/migrations/.

BEGIN;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- =========================================
-- SEQUENCES
-- =========================================
CREATE SEQUENCE IF NOT EXISTS users_employee_number_seq;
CREATE SEQUENCE IF NOT EXISTS departments_department_number_seq;
CREATE SEQUENCE IF NOT EXISTS offices_office_number_seq;
CREATE SEQUENCE IF NOT EXISTS positions_position_number_seq;
CREATE SEQUENCE IF NOT EXISTS shifts_shift_number_seq;

-- =========================================
-- GENERIC updated_at TRIGGER
-- =========================================
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- =========================================
-- USERS / EMPLOYEES
-- =========================================
CREATE TABLE IF NOT EXISTS users (
  attendance_tracking_start_date DATE,
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_number INT UNIQUE DEFAULT nextval('users_employee_number_seq'),

  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'employee'
    CHECK (role IN ('admin', 'hr', 'employee', 'supervisor', 'mayor', 'mayor_office_staff', 'super_admin')),

  first_name TEXT,
  full_name TEXT NOT NULL,
  last_name TEXT,
  avatar_path TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,

  middle_name TEXT,
  suffix TEXT,
  sex TEXT,
  date_of_birth DATE,
  contact_number TEXT,
  address TEXT,
  civil_status TEXT,
  nationality TEXT,

  employment_type TEXT
    -- regular is retained for importing legacy accounts; new accounts use the seven types.
    CONSTRAINT users_employment_type_check CHECK (employment_type IN (
      'permanent', 'temporary', 'casual', 'contractual', 'coterminous',
      'job_order', 'contract_of_service', 'regular'
    )),
  salary_grade TEXT,
  date_hired DATE,
  employment_status TEXT DEFAULT 'active'
    CHECK (employment_status IN ('active', 'inactive', 'resigned', 'retired', 'terminated')),
  leave_credit_eligible BOOLEAN NOT NULL DEFAULT true,
  separation_date DATE,
  leave_credit_eligible_until DATE,

  biometric_user_id TEXT UNIQUE,

  auth_version INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT users_nonactive_access_leave_check
    CHECK (
      COALESCE(employment_status, 'active') = 'active'
      OR (is_active = false AND leave_credit_eligible = false)
    ),
  CONSTRAINT users_super_admin_not_employee_check
    CHECK (role <> 'super_admin' OR (employee_number IS NULL AND leave_credit_eligible = false)),
  CONSTRAINT chk_users_separation_after_hire
    CHECK (
      separation_date IS NULL
      OR date_hired IS NULL
      OR separation_date >= date_hired
    ),
  CONSTRAINT chk_users_credit_eligibility_end
    CHECK (
      leave_credit_eligible_until IS NULL
      OR (
        separation_date IS NOT NULL
        AND leave_credit_eligible_until = separation_date
      )
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS users_single_super_admin_idx
  ON users (role) WHERE role = 'super_admin';

CREATE UNIQUE INDEX IF NOT EXISTS users_single_active_mayor_idx
  ON users (role) WHERE role = 'mayor' AND is_active = true;

-- JO/COS start without credit accrual eligibility, including direct SQL imports.
CREATE OR REPLACE FUNCTION apply_jo_cos_credit_default() RETURNS trigger AS $$
BEGIN
  IF NEW.employment_type IN ('job_order','contract_of_service')
    AND (TG_OP='INSERT' OR NEW.employment_type IS DISTINCT FROM OLD.employment_type) THEN
    NEW.leave_credit_eligible := false;
    NEW.leave_credit_eligible_until := NULL;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_users_jo_cos_credit_default ON users;
CREATE TRIGGER trg_users_jo_cos_credit_default BEFORE INSERT OR UPDATE OF employment_type ON users
  FOR EACH ROW EXECUTE FUNCTION apply_jo_cos_credit_default();

CREATE TABLE IF NOT EXISTS account_creation_access (
  admin_user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  allowed BOOLEAN NOT NULL,
  updated_by UUID REFERENCES users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS dtr_admin_access (
  admin_user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  reports_allowed BOOLEAN NOT NULL DEFAULT false,
  manage_allowed BOOLEAN NOT NULL DEFAULT false,
  employees_allowed BOOLEAN NOT NULL DEFAULT false,
  leave_allowed BOOLEAN NOT NULL DEFAULT false,
  approvals_allowed BOOLEAN NOT NULL DEFAULT false,
  locator_allowed BOOLEAN NOT NULL DEFAULT false,
  updated_by UUID REFERENCES users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS rsp_admin_access (
  admin_user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  vacancies_allowed BOOLEAN NOT NULL DEFAULT false,
  recruitment_allowed BOOLEAN NOT NULL DEFAULT false,
  exams_allowed BOOLEAN NOT NULL DEFAULT false,
  forms_allowed BOOLEAN NOT NULL DEFAULT false,
  applications_allowed BOOLEAN NOT NULL DEFAULT false,
  exam_results_allowed BOOLEAN NOT NULL DEFAULT false,
  scheduling_allowed BOOLEAN NOT NULL DEFAULT false,
  final_requirements_allowed BOOLEAN NOT NULL DEFAULT false,
  form_bi_allowed BOOLEAN NOT NULL DEFAULT false,
  form_applicants_profile_allowed BOOLEAN NOT NULL DEFAULT false,
  form_selection_lineup_allowed BOOLEAN NOT NULL DEFAULT false,
  form_computation_of_points_allowed BOOLEAN NOT NULL DEFAULT false,
  form_work_experience_allowed BOOLEAN NOT NULL DEFAULT false,
  form_turn_around_time_allowed BOOLEAN NOT NULL DEFAULT false,
  form_ojt_allowed BOOLEAN NOT NULL DEFAULT false,
  updated_by UUID REFERENCES users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ld_admin_access (
  admin_user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  forms_allowed BOOLEAN NOT NULL DEFAULT false,
  daily_reports_allowed BOOLEAN NOT NULL DEFAULT false,
  requirements_allowed BOOLEAN NOT NULL DEFAULT false,
  form_tna_allowed BOOLEAN NOT NULL DEFAULT false,
  form_action_brainstorming_allowed BOOLEAN NOT NULL DEFAULT false,
  form_idp_allowed BOOLEAN NOT NULL DEFAULT false,
  form_lap_allowed BOOLEAN NOT NULL DEFAULT false,
  updated_by UUID REFERENCES users(id),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- =========================================
-- AUTH REFRESH TOKENS (PERSISTENT SESSIONS)
-- =========================================
CREATE TABLE IF NOT EXISTS auth_refresh_tokens (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  device_info TEXT,
  ip_address INET,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Password reset assistance requests handled by an administrator.
CREATE TABLE IF NOT EXISTS password_reset_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'closed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at TIMESTAMPTZ,
  handled_by UUID REFERENCES users(id) ON DELETE SET NULL,
  closed_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS password_reset_requests_open_user
  ON password_reset_requests(user_id) WHERE status IN ('pending', 'sent');
CREATE INDEX IF NOT EXISTS password_reset_requests_created
  ON password_reset_requests(created_at DESC);

-- =========================================
-- AUTH PASSWORD RESET OTPs (SEMAPHORE SMS)
-- =========================================
CREATE TABLE IF NOT EXISTS auth_password_reset_otps (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code_hash TEXT NOT NULL,
  sent_to TEXT,
  expires_at TIMESTAMPTZ NOT NULL,
  consumed_at TIMESTAMPTZ,
  failed_attempts INT NOT NULL DEFAULT 0,
  ip_address INET,
  assistance_request_id UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT auth_password_reset_otps_assistance_request_id_fkey FOREIGN KEY (assistance_request_id) REFERENCES password_reset_requests(id) ON DELETE SET NULL
);

-- =========================================
-- DEPARTMENTS
-- =========================================
CREATE TABLE IF NOT EXISTS departments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  department_number INT UNIQUE DEFAULT nextval('departments_department_number_seq'),
  name TEXT NOT NULL,
  description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_departments_name_not_blank CHECK (BTRIM(name) <> '')
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_departments_name_ci
  ON departments (LOWER(BTRIM(name)));

-- =========================================
-- OFFICES (branch / site; DocuTracker office routing + users.office_id)
-- =========================================
CREATE TABLE IF NOT EXISTS offices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  office_number INT UNIQUE DEFAULT nextval('offices_office_number_seq'),
  name TEXT NOT NULL UNIQUE,
  description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE users
  ADD COLUMN IF NOT EXISTS office_id UUID REFERENCES offices(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_users_office_id ON users(office_id) WHERE office_id IS NOT NULL;

-- =========================================
-- POSITIONS
-- =========================================
CREATE TABLE IF NOT EXISTS positions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  position_number INT UNIQUE DEFAULT nextval('positions_position_number_seq'),
  name TEXT NOT NULL,
  description TEXT,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  is_department_head BOOLEAN NOT NULL DEFAULT false,
  is_leave_final_reviewer BOOLEAN NOT NULL DEFAULT false,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_positions_name_not_blank CHECK (BTRIM(name) <> ''),
  CONSTRAINT chk_position_department_head_department
    CHECK (is_department_head = false OR department_id IS NOT NULL)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_positions_name_department_ci
  ON positions (
    LOWER(BTRIM(name)),
    (COALESCE(department_id, '00000000-0000-0000-0000-000000000000'::uuid))
  );

CREATE UNIQUE INDEX IF NOT EXISTS uq_active_leave_final_reviewer_position
  ON positions (is_leave_final_reviewer)
  WHERE is_leave_final_reviewer = true AND is_active = true;

-- Effective-dated official Department Head designations. Position rows retain
-- is_department_head as a compatibility indicator; authority is resolved here.
CREATE TABLE IF NOT EXISTS position_department_head_periods (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  position_id UUID NOT NULL REFERENCES positions(id) ON DELETE CASCADE,
  department_id UUID NOT NULL REFERENCES departments(id) ON DELETE RESTRICT,
  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_position_department_head_period_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

ALTER TABLE position_department_head_periods
  DROP CONSTRAINT IF EXISTS position_department_head_period_no_overlap;
ALTER TABLE position_department_head_periods
  ADD CONSTRAINT position_department_head_period_no_overlap
  EXCLUDE USING gist (
    department_id WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  )
  WHERE (is_active = true);

CREATE INDEX IF NOT EXISTS idx_position_department_head_periods_effective
  ON position_department_head_periods
    (position_id, department_id, effective_from, effective_to)
  WHERE is_active = true;

-- =========================================
-- SHIFTS / SCHEDULES
-- =========================================
CREATE OR REPLACE FUNCTION public.is_valid_shift_working_days(days INTEGER[])
RETURNS BOOLEAN
LANGUAGE SQL
IMMUTABLE
STRICT
AS $$
  SELECT cardinality(days) BETWEEN 1 AND 7
     AND days <@ ARRAY[1,2,3,4,5,6,7]::INTEGER[]
     AND cardinality(days) = (
       SELECT COUNT(DISTINCT day)::INTEGER
       FROM unnest(days) AS day
     );
$$;

CREATE TABLE IF NOT EXISTS shifts (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  shift_number INT UNIQUE DEFAULT nextval('shifts_shift_number_seq'),
  name TEXT NOT NULL UNIQUE,

  start_time TIME NOT NULL,
  end_time TIME NOT NULL,
  break_end TIME,
  break_start TIME,
  capture_window_minutes INT NOT NULL DEFAULT 120 CHECK (capture_window_minutes BETWEEN 0 AND 240),
  punch_mode TEXT NOT NULL DEFAULT 'auto'
    CONSTRAINT shifts_punch_mode_check
    CHECK (punch_mode IN ('auto', 'full_day', 'am_only', 'pm_only', 'single_session')),

  grace_period_minutes INT NOT NULL DEFAULT 0
    CONSTRAINT shifts_grace_period_range_check
    CHECK (grace_period_minutes BETWEEN 0 AND 240),

  working_days INT[] NOT NULL DEFAULT ARRAY[1,2,3,4,5]
    CONSTRAINT shifts_working_days_check
    CHECK (public.is_valid_shift_working_days(working_days)),
  is_active BOOLEAN NOT NULL DEFAULT true,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON COLUMN shifts.working_days IS 'ISO weekday: 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat, 7=Sun';
COMMENT ON COLUMN shifts.punch_mode IS 'Attendance punch interpretation: auto, full_day, am_only, pm_only, or single_session.';

-- =========================================
-- ATTENDANCE POLICIES
-- =========================================
CREATE TABLE IF NOT EXISTS attendance_policies (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL UNIQUE,
  description TEXT,

  -- Structured computation settings (Shift holds grace period; keep it out of policy)
  work_hours_per_day NUMERIC(4,2) NOT NULL DEFAULT 8 CHECK (work_hours_per_day > 0),
  use_equivalent_day_conversion BOOLEAN NOT NULL DEFAULT true,

  -- Late settings
  deduct_late BOOLEAN NOT NULL DEFAULT false,
  max_late_minutes_per_month INT CHECK (max_late_minutes_per_month IS NULL OR max_late_minutes_per_month >= 0),
  convert_late_to_equivalent_day BOOLEAN NOT NULL DEFAULT true,

  -- Undertime settings
  deduct_undertime BOOLEAN NOT NULL DEFAULT true,
  convert_undertime_to_equivalent_day BOOLEAN NOT NULL DEFAULT true,

  -- Absence settings
  absent_equals_full_day_deduction BOOLEAN NOT NULL DEFAULT true,

  -- Advanced
  combine_late_and_undertime BOOLEAN NOT NULL DEFAULT false,
  deduction_multiplier NUMERIC(6,3) NOT NULL DEFAULT 1.0 CHECK (deduction_multiplier > 0),

  is_default BOOLEAN NOT NULL DEFAULT false,
  is_active BOOLEAN NOT NULL DEFAULT true,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_attendance_policies_single_default
ON attendance_policies (is_default)
WHERE is_default = true;

-- =========================================
-- BIOMETRIC DEVICES
-- =========================================
CREATE TABLE IF NOT EXISTS biometric_devices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  device_id TEXT UNIQUE,
  location TEXT,
  ip_address TEXT,
  vendor TEXT NOT NULL DEFAULT 'zkteco',
  last_sync_at TIMESTAMPTZ,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =========================================
-- ASSIGNMENTS
-- =========================================
CREATE TABLE IF NOT EXISTS assignments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  position_id UUID REFERENCES positions(id) ON DELETE SET NULL,
  shift_id UUID REFERENCES shifts(id) ON DELETE SET NULL,

  override_start_time TIME,
  override_end_time TIME,
  override_break_end TIME,

  effective_from DATE NOT NULL,
  effective_to DATE,

  is_active BOOLEAN NOT NULL DEFAULT true,
  remarks TEXT,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_assignment_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

DROP INDEX IF EXISTS uq_assignments_one_active_per_employee;

ALTER TABLE assignments
  DROP CONSTRAINT IF EXISTS assignments_no_overlapping_effective_ranges;
ALTER TABLE assignments
  ADD CONSTRAINT assignments_no_overlapping_effective_ranges
  EXCLUDE USING gist (
    employee_id WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  )
  WHERE (is_active = true);

CREATE INDEX IF NOT EXISTS idx_assignments_employee_effective_range
  ON assignments (employee_id, effective_from, effective_to)
  WHERE is_active = true;

-- Date-specific work/rest exceptions. Shift working_days remains the recurring
-- default; a row here overrides that default for one employee and one date.
CREATE TABLE IF NOT EXISTS employee_schedule_overrides (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  schedule_date DATE NOT NULL,
  is_working_day BOOLEAN NOT NULL,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT employee_schedule_overrides_employee_date_key
    UNIQUE (employee_id, schedule_date)
);

CREATE INDEX IF NOT EXISTS idx_employee_schedule_overrides_date_employee
  ON employee_schedule_overrides (schedule_date, employee_id);

-- Effective-dated delegates who may review alongside the official Department
-- Head. The primary reviewer is always resolved from the assignment history.
CREATE TABLE IF NOT EXISTS department_reviewer_backups (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  department_id UUID NOT NULL REFERENCES departments(id) ON DELETE RESTRICT,
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  backup_rank INT NOT NULL CHECK (backup_rank > 0),
  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  remarks TEXT,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_department_reviewer_backup_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

ALTER TABLE department_reviewer_backups
  DROP CONSTRAINT IF EXISTS department_reviewer_backup_rank_no_overlap;
ALTER TABLE department_reviewer_backups
  ADD CONSTRAINT department_reviewer_backup_rank_no_overlap
  EXCLUDE USING gist (
    department_id WITH =,
    backup_rank WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  )
  WHERE (is_active = true);

ALTER TABLE department_reviewer_backups
  DROP CONSTRAINT IF EXISTS department_reviewer_employee_no_overlap;
ALTER TABLE department_reviewer_backups
  ADD CONSTRAINT department_reviewer_employee_no_overlap
  EXCLUDE USING gist (
    department_id WITH =,
    employee_id WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  )
  WHERE (is_active = true);

CREATE INDEX IF NOT EXISTS idx_department_reviewer_backups_effective
  ON department_reviewer_backups
    (department_id, effective_from, effective_to, backup_rank)
  WHERE is_active = true;

CREATE TABLE IF NOT EXISTS leave_final_reviewer_backups (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  backup_rank INTEGER NOT NULL CHECK (backup_rank > 0),
  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_leave_final_reviewer_backup_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

ALTER TABLE positions
  ADD COLUMN IF NOT EXISTS is_leave_final_reviewer BOOLEAN NOT NULL DEFAULT false;

ALTER TABLE leave_final_reviewer_backups
  DROP CONSTRAINT IF EXISTS leave_final_reviewer_backup_employee_no_overlap;
ALTER TABLE leave_final_reviewer_backups
  ADD CONSTRAINT leave_final_reviewer_backup_employee_no_overlap
  EXCLUDE USING gist (
    employee_id WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  ) WHERE (is_active = true);
ALTER TABLE leave_final_reviewer_backups
  DROP CONSTRAINT IF EXISTS leave_final_reviewer_backup_rank_no_overlap;
ALTER TABLE leave_final_reviewer_backups
  ADD CONSTRAINT leave_final_reviewer_backup_rank_no_overlap
  EXCLUDE USING gist (
    backup_rank WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  ) WHERE (is_active = true);

-- =========================================
-- EMPLOYEE OTHER POSITIONS / DESIGNATIONS
-- =========================================
CREATE TABLE IF NOT EXISTS employee_other_positions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  department_id UUID NOT NULL REFERENCES departments(id) ON DELETE RESTRICT,
  position_id UUID NOT NULL REFERENCES positions(id) ON DELETE RESTRICT,
  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  remarks TEXT,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_employee_other_position_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE INDEX IF NOT EXISTS idx_employee_other_positions_employee
  ON employee_other_positions (employee_id, effective_from DESC);

CREATE INDEX IF NOT EXISTS idx_employee_other_positions_position
  ON employee_other_positions (position_id);

CREATE INDEX IF NOT EXISTS idx_employee_other_positions_duplicate_lookup
  ON employee_other_positions (
    employee_id,
    department_id,
    position_id,
    effective_from,
    effective_to
  )
  WHERE is_active = true;

-- =========================================
-- POLICY ASSIGNMENTS
-- =========================================
CREATE TABLE IF NOT EXISTS policy_assignments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  attendance_policy_id UUID NOT NULL REFERENCES attendance_policies(id) ON DELETE RESTRICT,

  employee_id UUID REFERENCES users(id) ON DELETE CASCADE,
  department_id UUID REFERENCES departments(id) ON DELETE CASCADE,
  shift_id UUID REFERENCES shifts(id) ON DELETE CASCADE,

  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_policy_assignment_target
    CHECK (
      employee_id IS NOT NULL
      OR department_id IS NOT NULL
      OR shift_id IS NOT NULL
    ),

  CONSTRAINT chk_policy_assignment_dates
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

ALTER TABLE policy_assignments
  DROP CONSTRAINT IF EXISTS policy_assignments_no_overlapping_employee_ranges;
ALTER TABLE policy_assignments
  ADD CONSTRAINT policy_assignments_no_overlapping_employee_ranges
  EXCLUDE USING gist (
    employee_id WITH =,
    daterange(effective_from, effective_to, '[]') WITH &&
  )
  WHERE (
    is_active = true
    AND employee_id IS NOT NULL
    AND department_id IS NULL
    AND shift_id IS NULL
  );

-- =========================================
-- HOLIDAYS
-- =========================================
CREATE TABLE IF NOT EXISTS holidays (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  date_from DATE NOT NULL,
  date_to DATE NOT NULL,
  name TEXT NOT NULL,
  holiday_type TEXT NOT NULL DEFAULT 'regular'
    CHECK (holiday_type IN ('regular', 'special', 'local', 'work_suspension')),
  description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  recurring BOOLEAN NOT NULL DEFAULT false,
  coverage TEXT NOT NULL DEFAULT 'whole_day'
    CHECK (coverage IN ('whole_day', 'am_only', 'pm_only')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_holidays_date_range CHECK (date_to >= date_from),
  CONSTRAINT uq_holidays_name_range UNIQUE (name, date_from, date_to)
);

CREATE TABLE IF NOT EXISTS holiday_default_templates (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  country_code TEXT NOT NULL DEFAULT 'PH',
  year INTEGER NOT NULL,
  label TEXT NOT NULL,
  source TEXT,
  note TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT uq_holiday_default_templates_country_year UNIQUE (country_code, year)
);

CREATE TABLE IF NOT EXISTS holiday_default_template_items (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  template_id UUID NOT NULL REFERENCES holiday_default_templates(id) ON DELETE CASCADE,
  date_from DATE NOT NULL,
  date_to DATE NOT NULL,
  name TEXT NOT NULL,
  holiday_type TEXT NOT NULL DEFAULT 'regular'
    CHECK (holiday_type IN ('regular', 'special', 'local', 'work_suspension')),
  description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  recurring BOOLEAN NOT NULL DEFAULT false,
  coverage TEXT NOT NULL DEFAULT 'whole_day'
    CHECK (coverage IN ('whole_day', 'am_only', 'pm_only')),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_holiday_default_template_items_date_range CHECK (date_to >= date_from),
  CONSTRAINT uq_holiday_default_template_items_row UNIQUE (template_id, name, date_from, date_to)
);

-- =========================================
-- SHARED LEAVE / LOCATOR APPROVAL WORKFLOWS
-- =========================================
CREATE TABLE IF NOT EXISTS approval_workflows (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 100),
  current_version INTEGER NOT NULL DEFAULT 1 CHECK (current_version > 0),
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS approval_workflows_name_unique
  ON approval_workflows (lower(name));

CREATE TABLE IF NOT EXISTS approval_workflow_versions (
  workflow_id UUID NOT NULL REFERENCES approval_workflows(id),
  version INTEGER NOT NULL CHECK (version > 0),
  steps JSONB NOT NULL CHECK (
    jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) BETWEEN 1 AND 20
  ),
  employment_types TEXT[],
  self_filing_signatory_policy TEXT NOT NULL DEFAULT 'mayor'
    CONSTRAINT approval_workflow_versions_print_policy_check
    CHECK (self_filing_signatory_policy IN ('mayor', 'blank', 'actual_reviewer')),
  backup_signatory_policy TEXT NOT NULL DEFAULT 'keep_primary'
    CONSTRAINT approval_workflow_versions_backup_print_policy_check
    CHECK (backup_signatory_policy IN ('keep_primary', 'actual_reviewer')),
  created_by UUID REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (workflow_id, version)
);

-- =========================================
-- LEAVE TYPES
-- =========================================
CREATE TABLE IF NOT EXISTS leave_types (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  approval_workflow_id UUID REFERENCES approval_workflows(id),
  name TEXT NOT NULL UNIQUE,
  display_name TEXT,
  description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  employee_can_file BOOLEAN NOT NULL DEFAULT true,
  admin_can_file BOOLEAN NOT NULL DEFAULT true,
  allow_approved_paper_filing BOOLEAN NOT NULL DEFAULT false,
  admin_only BOOLEAN NOT NULL DEFAULT false,
  allows_past_dates BOOLEAN NOT NULL DEFAULT true,
  requires_attachment BOOLEAN NOT NULL DEFAULT false,
  requires_attachment_when_over_days NUMERIC,
  max_days NUMERIC,
  minimum_advance_days INTEGER,
  minimum_service_months INTEGER NOT NULL DEFAULT 0,
  first_year_allowance TEXT NOT NULL DEFAULT 'full',
  affects_dtr_normally BOOLEAN NOT NULL DEFAULT true,
  balance_ledger_type TEXT NOT NULL DEFAULT 'none',
  entitlement_basis TEXT NOT NULL DEFAULT 'per_request',
  sex_eligibility TEXT NOT NULL DEFAULT 'any',
  eligible_employment_types TEXT[],
  accrues_monthly BOOLEAN NOT NULL DEFAULT false,
  accrual_monthly_rate NUMERIC(6,3),
  accrual_annual_cap NUMERIC(10,3),
  employee_detail_schema JSONB NOT NULL DEFAULT '[]'::jsonb,
  is_system BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_leave_type_employee_detail_schema_array CHECK (
    jsonb_typeof(employee_detail_schema) = 'array'
  ),
  CONSTRAINT chk_leave_type_entitlement_basis CHECK (
    entitlement_basis IN ('accrual', 'annual', 'per_event', 'per_request', 'compliance')
  ),
  CONSTRAINT chk_leave_type_sex_eligibility CHECK (
    sex_eligibility IN ('any', 'female', 'male')
  ),
  CONSTRAINT chk_leave_type_employment_eligibility CHECK (
    eligible_employment_types IS NULL OR (
      cardinality(eligible_employment_types) > 0
      AND array_position(eligible_employment_types, NULL) IS NULL
      AND eligible_employment_types <@ ARRAY[
        'permanent', 'temporary', 'casual', 'contractual', 'coterminous',
        'job_order', 'contract_of_service', 'regular'
      ]::text[]
    )
  ),
  CONSTRAINT chk_leave_type_max_days_positive CHECK (
    max_days IS NULL OR max_days > 0
  ),
  CONSTRAINT chk_leave_type_attachment_threshold_positive CHECK (
    requires_attachment_when_over_days IS NULL OR requires_attachment_when_over_days > 0
  ),
  CONSTRAINT chk_leave_type_minimum_advance_days_nonnegative CHECK (
    minimum_advance_days IS NULL OR minimum_advance_days >= 0
  ),
  CONSTRAINT chk_leave_type_minimum_service_months CHECK (
    minimum_service_months BETWEEN 0 AND 1200
  ),
  CONSTRAINT chk_leave_type_first_year_allowance CHECK (
    first_year_allowance IN ('full', 'prorated') AND (
      first_year_allowance = 'full' OR (
        entitlement_basis = 'annual' AND max_days IS NOT NULL AND max_days > 0
        AND balance_ledger_type = 'none'
      )
    )
  )
);

-- Seed leave types (names must match Flutter LeaveType enum .value for API lookup).
INSERT INTO leave_types (name, description, is_active, allow_approved_paper_filing)
VALUES
  ('vacationLeave', 'Vacation Leave', true, true),
  ('mandatoryForcedLeave', 'Mandatory/Forced Leave', true, true),
  ('sickLeave', 'Sick Leave', true, true),
  ('maternityLeave', 'Maternity Leave', true, true),
  ('paternityLeave', 'Paternity Leave', true, true),
  ('specialPrivilegeLeave', 'Special Privilege Leave', true, true),
  ('soloParentLeave', 'Solo Parent Leave', true, true),
  ('studyLeave', 'Study Leave', true, true),
  ('tenDayVawcLeave', '10-Day VAWC Leave', true, true),
  ('rehabilitationPrivilege', 'Rehabilitation Privilege', true, true),
  ('specialLeaveBenefitsForWomen', 'Special Leave Benefits for Women', true, true),
  ('specialEmergencyCalamityLeave', 'Special Emergency (Calamity) Leave', true, true),
  ('adoptionLeave', 'Adoption Leave', true, true),
  ('others', 'Others', true, true)
ON CONFLICT (name) DO NOTHING;

UPDATE leave_types
SET display_name = COALESCE(NULLIF(display_name, ''), description, name),
    employee_can_file = true,
    admin_only = false,
    allows_past_dates = CASE WHEN name IN ('vacationLeave', 'specialPrivilegeLeave') THEN false ELSE true END,
    requires_attachment = CASE
      WHEN name IN (
        'maternityLeave',
        'paternityLeave',
        'soloParentLeave',
        'studyLeave',
        'tenDayVawcLeave',
        'rehabilitationPrivilege',
        'specialLeaveBenefitsForWomen',
        'specialEmergencyCalamityLeave',
        'adoptionLeave',
        'others'
      ) THEN true
      ELSE false
    END,
    requires_attachment_when_over_days = CASE WHEN name = 'sickLeave' THEN 5 ELSE NULL END,
    max_days = CASE
      WHEN name = 'mandatoryForcedLeave' THEN 5
      WHEN name = 'maternityLeave' THEN 105
      WHEN name = 'paternityLeave' THEN 7
      WHEN name = 'specialPrivilegeLeave' THEN 3
      WHEN name = 'soloParentLeave' THEN 7
      WHEN name = 'studyLeave' THEN 180
      WHEN name = 'tenDayVawcLeave' THEN 10
      WHEN name = 'rehabilitationPrivilege' THEN 180
      WHEN name = 'specialLeaveBenefitsForWomen' THEN 60
      WHEN name = 'specialEmergencyCalamityLeave' THEN 5
      ELSE NULL
    END,
    minimum_advance_days = CASE
      WHEN name IN ('vacationLeave', 'soloParentLeave', 'specialLeaveBenefitsForWomen') THEN 5
      WHEN name = 'specialPrivilegeLeave' THEN 7
      ELSE NULL
    END,
    affects_dtr_normally = true,
    is_system = name IN (
      'vacationLeave',
      'mandatoryForcedLeave',
      'sickLeave',
      'maternityLeave',
      'paternityLeave',
      'specialPrivilegeLeave',
      'soloParentLeave',
      'studyLeave',
      'tenDayVawcLeave',
      'rehabilitationPrivilege',
      'specialLeaveBenefitsForWomen',
      'specialEmergencyCalamityLeave',
      'adoptionLeave',
      'others'
    ),
    balance_ledger_type = CASE
      WHEN name = 'mandatoryForcedLeave' THEN 'vacationLeave'
      WHEN name IN ('vacationLeave', 'sickLeave') THEN name
      ELSE 'none'
    END,
    entitlement_basis = CASE
      WHEN name IN ('vacationLeave', 'sickLeave') THEN 'accrual'
      WHEN name IN ('specialPrivilegeLeave', 'soloParentLeave', 'tenDayVawcLeave') THEN 'annual'
      WHEN name = 'mandatoryForcedLeave' THEN 'compliance'
      WHEN name IN (
        'maternityLeave',
        'paternityLeave',
        'rehabilitationPrivilege',
        'specialLeaveBenefitsForWomen',
        'specialEmergencyCalamityLeave',
        'adoptionLeave'
      ) THEN 'per_event'
      ELSE 'per_request'
    END,
    sex_eligibility = CASE
      WHEN name IN ('maternityLeave', 'tenDayVawcLeave', 'specialLeaveBenefitsForWomen') THEN 'female'
      WHEN name = 'paternityLeave' THEN 'male'
      ELSE 'any'
    END,
    accrues_monthly = CASE WHEN name IN ('vacationLeave', 'sickLeave') THEN true ELSE false END,
    accrual_monthly_rate = CASE WHEN name IN ('vacationLeave', 'sickLeave') THEN 1.25 ELSE NULL END,
    accrual_annual_cap = NULL;

-- Built-in filing defaults exclude JO/COS. Keep existing legacy Regular access.
UPDATE leave_types SET eligible_employment_types = ARRAY[
  'permanent','temporary','casual','contractual','coterminous','regular']::text[]
WHERE is_system = true AND eligible_employment_types IS NULL;

-- =========================================
-- LEAVE REQUESTS
-- =========================================
CREATE TABLE IF NOT EXISTS leave_requests (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- user_id mirrors employee_id. Both are written on every INSERT.
  -- NOT NULL enforced here so fresh installs match the Phase 3 migration constraint.
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  leave_type_id UUID REFERENCES leave_types(id) ON DELETE SET NULL,

  -- Drafts may be saved before the employee knows the complete date range.
  -- Submission routes still require and validate both dates.
  start_date DATE,
  end_date DATE,
  total_days NUMERIC(5,2),
  number_of_days NUMERIC(5,2),

  reason TEXT,
  -- Supporting document attachment (PDF, JPG, JPEG, PNG)
  attachment_name TEXT,
  attachment_path TEXT,
  attachment_mime_type TEXT,
  attachment_uploaded_at TIMESTAMPTZ,
  -- Whitelisted employee-editable leave-specific fields only.
  details JSONB,
  -- Server-generated official identity/assignment fields used by forms and exports.
  employee_official_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- Field labels/types frozen with the request for reliable historical display.
  employee_detail_schema_snapshot JSONB NOT NULL DEFAULT '[]'::jsonb,
  paper_approval_record JSONB,
  workflow_snapshot JSONB,
  signature_revision INTEGER NOT NULL DEFAULT 1 CHECK (signature_revision > 0),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN (
      'draft',
      'pending',                       -- legacy alias for pending_hr
      'pending_department_head',       -- awaiting department head approval
      'pending_hr',                    -- awaiting HR/admin final approval
      'rejected_by_department_head',   -- department head rejected
      'rejected_by_hr',                -- HR/admin rejected
      'returned',                      -- sent back to employee for correction
      'approved',                      -- final approval by HR/admin
      'rejected',                      -- legacy single-stage rejection
      'cancelled'                      -- employee cancelled
    )),

  discarded_at TIMESTAMPTZ,

  reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,
  reviewer_remarks TEXT,
  recommendation_remarks TEXT,
  disapproval_reason TEXT,
  reviewed_at TIMESTAMPTZ,

  -- Review routing is frozen when the employee submits or resubmits.
  review_department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  assigned_department_head_id UUID REFERENCES users(id) ON DELETE SET NULL,

  -- Authoritative final HR allocation. Only paid days consume leave credits.
  approved_days_with_pay NUMERIC(5,2),
  approved_days_without_pay NUMERIC(5,2),
  approved_other_details TEXT,
  -- Exact amount held in leave_balances.pending_days while this request is pending.
  -- NULL means the leave type does not use a credit balance.
  reserved_credit_days NUMERIC(10,3),

  approved_by UUID REFERENCES users(id) ON DELETE SET NULL,
  approved_at TIMESTAMPTZ,
  -- Mayor identity frozen at final approval so historical forms remain stable.
  approving_authority_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT chk_leave_dates CHECK (end_date >= start_date),
  CONSTRAINT chk_leave_submission_dates CHECK (
    status = 'draft' OR (start_date IS NOT NULL AND end_date IS NOT NULL)
  ),
  CONSTRAINT chk_leave_total_days CHECK (
    (total_days IS NULL OR total_days >= 0)
    AND (number_of_days IS NULL OR number_of_days >= 0)
  ),
  CONSTRAINT chk_leave_employee_official_snapshot_object CHECK (
    jsonb_typeof(employee_official_snapshot) = 'object'
  ),
  CONSTRAINT chk_leave_employee_detail_schema_snapshot_array CHECK (
    jsonb_typeof(employee_detail_schema_snapshot) = 'array'
  ),
  CONSTRAINT chk_leave_approved_days_nonnegative CHECK (
    (approved_days_with_pay IS NULL OR approved_days_with_pay >= 0)
    AND (approved_days_without_pay IS NULL OR approved_days_without_pay >= 0)
  ),
  CONSTRAINT chk_leave_reserved_credit_days_nonnegative CHECK (
    reserved_credit_days IS NULL OR reserved_credit_days >= 0
  ),
  CONSTRAINT chk_leave_approving_authority_snapshot_object CHECK (
    jsonb_typeof(approving_authority_snapshot) = 'object'
  )
);
CREATE INDEX IF NOT EXISTS idx_leave_requests_review_department
  ON leave_requests(review_department_id);
CREATE INDEX IF NOT EXISTS idx_leave_requests_assigned_department_head
  ON leave_requests(assigned_department_head_id, status);

CREATE TABLE IF NOT EXISTS leave_request_department_reviewers (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  leave_request_id UUID NOT NULL REFERENCES leave_requests(id) ON DELETE CASCADE,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,
  reviewer_name_snapshot TEXT NOT NULL,
  reviewer_role TEXT NOT NULL CHECK (reviewer_role IN ('primary', 'backup')),
  backup_rank INT CHECK (backup_rank IS NULL OR backup_rank > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_leave_reviewer_rank CHECK (
    (reviewer_role = 'primary' AND backup_rank IS NULL)
    OR (reviewer_role = 'backup' AND backup_rank IS NOT NULL)
  ),
  UNIQUE (leave_request_id, reviewer_id)
);

CREATE INDEX IF NOT EXISTS idx_leave_request_department_reviewers_user
  ON leave_request_department_reviewers(reviewer_id, leave_request_id);

-- =========================================
-- LEAVE BALANCES
-- =========================================
CREATE TABLE IF NOT EXISTS leave_balances (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- leave_type must match a value in leave_types(name).
  -- FK enforces referential integrity; CHECK is a belt-and-suspenders guard.
  leave_type TEXT NOT NULL,
  earned_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (earned_days >= 0),
  used_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (used_days >= 0),
  pending_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (pending_days >= 0),
  adjusted_days NUMERIC(10,3) NOT NULL DEFAULT 0,
  as_of_date DATE,
  last_accrual_date DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(user_id, leave_type),
  CONSTRAINT fk_leave_balances_leave_type
    FOREIGN KEY (leave_type) REFERENCES leave_types(name)
    ON UPDATE CASCADE
    ON DELETE RESTRICT
    DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT chk_leave_balances_leave_type CHECK (
    leave_type IN (
      'vacationLeave',
      'mandatoryForcedLeave',
      'sickLeave',
      'maternityLeave',
      'paternityLeave',
      'specialPrivilegeLeave',
      'soloParentLeave',
      'studyLeave',
      'tenDayVawcLeave',
      'rehabilitationPrivilege',
      'specialLeaveBenefitsForWomen',
      'specialEmergencyCalamityLeave',
      'adoptionLeave',
      'others'
    )
  )
);
CREATE INDEX IF NOT EXISTS idx_leave_balances_user_id ON leave_balances(user_id);

-- =========================================
-- LEAVE REQUEST HISTORY (AUDIT TRAIL)
-- =========================================
CREATE TABLE IF NOT EXISTS leave_request_history (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  leave_request_id UUID NOT NULL REFERENCES leave_requests(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  from_status TEXT,
  to_status TEXT NOT NULL,
  acted_by UUID REFERENCES users(id) ON DELETE SET NULL,
  acted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  remarks TEXT,
  metadata_json JSONB
);
CREATE INDEX IF NOT EXISTS idx_leave_request_history_leave_request_id
  ON leave_request_history(leave_request_id);

-- =========================================
-- LEGACY LEAVE BALANCE DEDUCTION HISTORY
-- =========================================
-- Retained while leaveRoutes still initializes this compatibility table.
CREATE TABLE IF NOT EXISTS leave_balance_deduction_history (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  leave_type TEXT NOT NULL,
  deducted_days NUMERIC NOT NULL,
  remaining_days NUMERIC,
  remarks TEXT,
  applied_by UUID REFERENCES users(id) ON DELETE SET NULL,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  metadata_json JSONB
);
CREATE INDEX IF NOT EXISTS idx_leave_balance_deduction_history_user_applied
  ON leave_balance_deduction_history(user_id, applied_at DESC);

-- =========================================
-- LEAVE ATTACHMENT ACCESS LOG (SENSITIVE-DOCUMENT AUDIT)
-- =========================================
CREATE TABLE IF NOT EXISTS leave_attachment_access_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  leave_request_id UUID REFERENCES leave_requests(id) ON DELETE SET NULL,
  attachment_name TEXT,
  accessed_by UUID REFERENCES users(id) ON DELETE SET NULL,
  actor_role TEXT,
  access_reason TEXT NOT NULL,
  access_outcome TEXT NOT NULL
    CHECK (access_outcome IN ('allowed', 'denied', 'missing_attachment', 'missing_file')),
  ip_address TEXT,
  user_agent TEXT,
  accessed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_leave_attachment_access_request_time
  ON leave_attachment_access_logs(leave_request_id, accessed_at DESC);
CREATE INDEX IF NOT EXISTS idx_leave_attachment_access_actor_time
  ON leave_attachment_access_logs(accessed_by, accessed_at DESC);

-- =========================================
-- LEAVE BALANCE LEDGER (append-only audit of bucket changes)
-- =========================================
-- Distinct from leave_request_history (workflow). Records earned/pending/used/adjusted movements.
CREATE TABLE IF NOT EXISTS leave_balance_ledger (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  leave_type TEXT NOT NULL,
  action TEXT NOT NULL,
  affected_bucket TEXT NOT NULL,
  days_changed NUMERIC NOT NULL DEFAULT 0,
  old_value NUMERIC,
  new_value NUMERIC,
  related_leave_request_id UUID REFERENCES leave_requests(id) ON DELETE SET NULL,
  actor_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  actor_kind TEXT NOT NULL DEFAULT 'user',
  remarks TEXT,
  metadata_json JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_leave_balance_ledger_user_created
  ON leave_balance_ledger(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS leave_opening_balance_setups (
  user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  cutoff_date DATE NOT NULL CHECK (EXTRACT(DAY FROM (cutoff_date + 1)) = 1),
  sick_leave_days NUMERIC(10,3) NOT NULL CHECK (sick_leave_days >= 0),
  vacation_leave_days NUMERIC(10,3) NOT NULL CHECK (vacation_leave_days >= 0),
  reason TEXT NOT NULL CHECK (btrim(reason) <> ''),
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  qualifying_leave_days NUMERIC(10,3),
  usage_reference TEXT,
  usage_verified_by UUID REFERENCES users(id) ON DELETE SET NULL,
  usage_verified_at TIMESTAMPTZ,
  CONSTRAINT leave_opening_usage_check CHECK (
    (qualifying_leave_days IS NULL AND usage_reference IS NULL AND usage_verified_at IS NULL)
    OR (qualifying_leave_days IS NOT NULL AND qualifying_leave_days BETWEEN 0 AND 366
      AND usage_reference IS NOT NULL AND btrim(usage_reference) <> '' AND usage_verified_at IS NOT NULL)
  )
);

CREATE INDEX IF NOT EXISTS idx_leave_balance_ledger_action
  ON leave_balance_ledger(action);
CREATE INDEX IF NOT EXISTS idx_leave_balance_ledger_leave_request
  ON leave_balance_ledger(related_leave_request_id)
  WHERE related_leave_request_id IS NOT NULL;

-- =========================================
-- PRIMARY EMPLOYEE REVIEWER DESIGNATIONS
-- =========================================
CREATE TABLE IF NOT EXISTS primary_reviewer_designations (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  scope_key TEXT NOT NULL,
  department_id UUID REFERENCES departments(id) ON DELETE RESTRICT,
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  position_id UUID REFERENCES positions(id) ON DELETE SET NULL,
  position_title_snapshot TEXT,
  effective_from DATE NOT NULL,
  effective_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CHECK ((scope_key = 'final_hr' AND department_id IS NULL)
    OR (department_id IS NOT NULL AND scope_key = 'department:' || department_id::text)),
  CONSTRAINT primary_reviewer_no_overlap EXCLUDE USING gist (
    scope_key WITH =, daterange(effective_from, effective_to, '[]') WITH &&
  ) WHERE (is_active = true)
);

-- =========================================
-- MONTHLY LEAVE ACCRUAL POSTINGS
-- =========================================
-- One reconcilable earned-credit posting per employee, leave type, and service month.
CREATE TABLE IF NOT EXISTS leave_monthly_accrual_postings (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  service_month DATE NOT NULL,
  leave_type TEXT NOT NULL,
  credited_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (credited_days >= 0),
  accrual_rate NUMERIC(6,3) NOT NULL CHECK (accrual_rate >= 0),
  metadata_json JSONB,
  posted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_leave_monthly_accrual_posting
    UNIQUE (user_id, service_month, leave_type),
  CONSTRAINT chk_leave_monthly_accrual_service_month
    CHECK (EXTRACT(DAY FROM service_month) = 1),
  CONSTRAINT fk_leave_monthly_accrual_posting_leave_type
    FOREIGN KEY (leave_type) REFERENCES leave_types(name)
    ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_leave_monthly_accrual_postings_month
  ON leave_monthly_accrual_postings(service_month, user_id);

-- =========================================
-- MONTH-END DTR LEAVE DEDUCTIONS
-- =========================================
-- One idempotent Vacation Leave posting per employee and completed service month.
CREATE TABLE IF NOT EXISTS leave_attendance_deductions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  service_month DATE NOT NULL,
  leave_type TEXT NOT NULL DEFAULT 'vacationLeave',
  late_minutes INT NOT NULL DEFAULT 0 CHECK (late_minutes >= 0),
  undertime_minutes INT NOT NULL DEFAULT 0 CHECK (undertime_minutes >= 0),
  absence_minutes INT NOT NULL DEFAULT 0 CHECK (absence_minutes >= 0),
  computed_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (computed_days >= 0),
  deducted_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (deducted_days >= 0),
  without_pay_days NUMERIC(10,3) NOT NULL DEFAULT 0 CHECK (without_pay_days >= 0),
  source_record_count INT NOT NULL DEFAULT 0 CHECK (source_record_count >= 0),
  metadata_json JSONB,
  posted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_leave_attendance_deduction_month
    UNIQUE (user_id, service_month, leave_type),
  CONSTRAINT chk_leave_attendance_service_month
    CHECK (EXTRACT(DAY FROM service_month) = 1),
  CONSTRAINT chk_leave_attendance_vacation_only
    CHECK (leave_type = 'vacationLeave'),
  CONSTRAINT fk_leave_attendance_deduction_leave_type
    FOREIGN KEY (leave_type) REFERENCES leave_types(name)
    ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_leave_attendance_deductions_month
  ON leave_attendance_deductions(service_month, user_id);

-- Completed DTR months changed after posting are reconciled on the next
-- scheduled or manual month-end run. One row per employee/month is reopened
-- whenever another correction occurs.
CREATE TABLE IF NOT EXISTS dtr_month_end_reconciliation_queue (
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  service_month DATE NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'reconciled')),
  reason TEXT NOT NULL,
  metadata_json JSONB,
  required_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_attempt_at TIMESTAMPTZ,
  attempt_count INT NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  last_error TEXT,
  reconciled_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (employee_id, service_month),
  CONSTRAINT chk_dtr_reconciliation_service_month
    CHECK (EXTRACT(DAY FROM service_month) = 1)
);

CREATE INDEX IF NOT EXISTS idx_dtr_reconciliation_pending_month
  ON dtr_month_end_reconciliation_queue(service_month, required_at)
  WHERE status = 'pending';

-- =========================================
-- IN-APP NOTIFICATIONS (DTR / leave / future modules)
-- =========================================
CREATE TABLE IF NOT EXISTS user_notifications (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  category TEXT NOT NULL DEFAULT 'general',
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  read_at TIMESTAMPTZ,
  reference_type TEXT,
  reference_id UUID,
  metadata JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_user_notifications_user_id ON user_notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_user_notifications_read_at ON user_notifications(user_id, read_at);
CREATE INDEX IF NOT EXISTS idx_user_notifications_created_at ON user_notifications(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS leave_month_end_notification_state (
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  service_month DATE NOT NULL CHECK (EXTRACT(DAY FROM service_month) = 1),
  totals JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, service_month)
);
CREATE UNIQUE INDEX IF NOT EXISTS user_notifications_month_end_failure_idx
  ON user_notifications(user_id, (metadata->>'service_month'))
  WHERE type = 'leave_month_end_failed';

CREATE TABLE IF NOT EXISTS user_push_tokens (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT 'unknown',
  device_id TEXT,
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_user_push_tokens_token_unique
  ON user_push_tokens(token);

CREATE INDEX IF NOT EXISTS idx_user_push_tokens_user_active
  ON user_push_tokens(user_id)
  WHERE revoked_at IS NULL;

-- =========================================
-- LOCATOR REQUESTS
-- =========================================
CREATE TABLE IF NOT EXISTS locator_request_types (
  approval_route TEXT NOT NULL DEFAULT 'hr',
  mayor_employment_types TEXT[],
  approval_workflow_id UUID REFERENCES approval_workflows(id),
  employee_detail_schema JSONB NOT NULL DEFAULT '[]'::jsonb,
  filing_access TEXT NOT NULL DEFAULT 'employee',
  auto_approve_admin BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT chk_locator_approval_route CHECK (
    approval_route IN ('hr','mayor','mayor_direct')
    AND (approval_route = 'hr' OR NOT auto_approve_admin)
  ),
  CONSTRAINT chk_locator_filing_access CHECK (filing_access IN ('employee','admin','both') AND (NOT auto_approve_admin OR filing_access <> 'employee')),
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  code TEXT NOT NULL
    CONSTRAINT chk_locator_request_types_code_format
    CHECK (code ~ '^[a-z0-9_][a-z0-9_-]{1,63}$')
    UNIQUE,
  label TEXT NOT NULL
    CONSTRAINT chk_locator_request_types_label_length
    CHECK (label = btrim(label) AND char_length(label) BETWEEN 1 AND 100),
  short_label TEXT NOT NULL
    CONSTRAINT chk_locator_request_types_short_label_length
    CHECK (short_label = btrim(short_label) AND char_length(short_label) BETWEEN 1 AND 40),
  location_label TEXT NOT NULL DEFAULT 'Office / Destination'
    CONSTRAINT chk_locator_request_types_location_label_length
    CHECK (location_label = btrim(location_label) AND char_length(location_label) BETWEEN 1 AND 100),
  location_hint TEXT NOT NULL DEFAULT 'Enter office or destination'
    CONSTRAINT chk_locator_request_types_location_hint_length
    CHECK (location_hint = btrim(location_hint) AND char_length(location_hint) BETWEEN 1 AND 200),
  dtr_slot_label TEXT NOT NULL DEFAULT 'On Field'
    CONSTRAINT chk_locator_request_types_dtr_slot_label_length
    CHECK (dtr_slot_label = btrim(dtr_slot_label) AND char_length(dtr_slot_label) BETWEEN 1 AND 40),
  dtr_print_label TEXT NOT NULL DEFAULT 'ON FIELD'
    CONSTRAINT chk_locator_request_types_dtr_print_label_length
    CHECK (dtr_print_label = btrim(dtr_print_label) AND char_length(dtr_print_label) BETWEEN 1 AND 40),
  requires_attachment BOOLEAN NOT NULL DEFAULT false,
  coverage_mode TEXT NOT NULL DEFAULT 'manual'
    CONSTRAINT locator_request_types_coverage_mode_check
    CHECK (coverage_mode IN ('manual', 'wfh')),
  is_active BOOLEAN NOT NULL DEFAULT true,
  is_system BOOLEAN NOT NULL DEFAULT false,
  sort_order INTEGER NOT NULL DEFAULT 0
    CONSTRAINT chk_locator_request_types_sort_order_nonnegative
    CHECK (sort_order >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO locator_request_types (
  code, label, short_label, location_label, location_hint,
  dtr_slot_label, dtr_print_label, requires_attachment,
  coverage_mode, is_active, is_system, sort_order
) VALUES
  ('locator', 'Locator / Official Business', 'Locator',
   'Office / Destination', 'Enter office or destination',
   'On Field', 'ON FIELD', false, 'manual', true, true, 10),
  ('pass_slip', 'Pass Slip', 'Pass Slip',
   'Destination / Location', 'Enter destination or location',
   'Pass Slip', 'PASS SLIP', false, 'manual', true, true, 20)
ON CONFLICT (code) DO UPDATE SET
  is_system = true,
  updated_at = now();

CREATE TABLE IF NOT EXISTS locator_slips (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  workflow_snapshot JSONB,
  employee_detail_schema_snapshot JSONB NOT NULL DEFAULT '[]'::jsonb,
  additional_details JSONB NOT NULL DEFAULT '{}'::jsonb,
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  assigned_department_head_id UUID REFERENCES users(id) ON DELETE SET NULL,
  print_signatories JSONB,
  signature_revision INTEGER NOT NULL DEFAULT 1,
  slip_date DATE NOT NULL,
  am_in BOOLEAN NOT NULL DEFAULT false,
  am_out BOOLEAN NOT NULL DEFAULT false,
  pm_in BOOLEAN NOT NULL DEFAULT false,
  pm_out BOOLEAN NOT NULL DEFAULT false,
  request_type TEXT NOT NULL DEFAULT 'locator',
  request_type_label_snapshot TEXT,
  request_type_short_label_snapshot TEXT,
  request_type_location_label_snapshot TEXT,
  request_type_location_hint_snapshot TEXT,
  request_type_dtr_slot_label_snapshot TEXT,
  request_type_dtr_print_label_snapshot TEXT,
  request_type_requires_attachment_snapshot BOOLEAN,
  request_type_coverage_mode_snapshot TEXT
    CONSTRAINT chk_locator_type_coverage_snapshot
    CHECK (
      request_type_coverage_mode_snapshot IS NULL
      OR request_type_coverage_mode_snapshot IN ('manual', 'wfh')
    ),
  request_type_snapshot_at TIMESTAMPTZ,
  office TEXT NOT NULL,
  reason TEXT NOT NULL,
  attachment_name TEXT,
  attachment_path TEXT,
  attachment_mime_type TEXT,
  attachment_uploaded_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'pending_department_head'
    CHECK (status IN (
      'pending',
      'pending_department_head',
      'pending_hr',
      'pending_mayor',
      'returned_for_correction',
      'approved',
      'revoked',
      'rejected_by_department_head',
      'rejected_by_hr',
      'cancelled'
    )),
  dept_head_reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,
  dept_head_reviewed_at TIMESTAMPTZ,
  dept_head_remarks TEXT,
  hr_reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,
  hr_reviewed_at TIMESTAMPTZ,
  hr_remarks TEXT,
  final_review_route TEXT NOT NULL DEFAULT 'hr',
  final_reviewer_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  is_retroactive_correction BOOLEAN NOT NULL DEFAULT false,
  paper_approval_record JSONB,
  retroactive_correction_reason TEXT,
  retroactive_corrected_by UUID REFERENCES users(id) ON DELETE SET NULL,
  retroactive_corrected_at TIMESTAMPTZ,
  revoked_by UUID REFERENCES users(id) ON DELETE SET NULL,
  revoked_at TIMESTAMPTZ,
  revocation_reason TEXT,
  month_end_reconciliation_required BOOLEAN NOT NULL DEFAULT false,
  month_end_reconciled_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_locator_correction_audit CHECK (
    is_retroactive_correction = false
    OR (
      retroactive_correction_reason IS NOT NULL
      AND char_length(btrim(retroactive_correction_reason)) BETWEEN 10 AND 1000
      AND retroactive_corrected_by IS NOT NULL
      AND retroactive_corrected_at IS NOT NULL
    )
  ),
  CONSTRAINT chk_locator_revocation_audit CHECK (
    status <> 'revoked'
    OR (
      revoked_by IS NOT NULL
      AND revoked_at IS NOT NULL
      AND revocation_reason IS NOT NULL
      AND char_length(btrim(revocation_reason)) BETWEEN 10 AND 1000
    )
  )
);

CREATE INDEX IF NOT EXISTS idx_locator_slips_employee
  ON locator_slips(employee_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_locator_slips_status
  ON locator_slips(status, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_locator_slips_department
  ON locator_slips(department_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_locator_slips_assigned_department_head
  ON locator_slips(assigned_department_head_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_locator_slips_date
  ON locator_slips(slip_date DESC);
CREATE INDEX IF NOT EXISTS idx_locator_slips_request_type
  ON locator_slips(request_type);
CREATE INDEX IF NOT EXISTS idx_locator_request_types_active
  ON locator_request_types(is_active, sort_order, label);

CREATE TABLE IF NOT EXISTS locator_slip_department_reviewers (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  locator_slip_id UUID NOT NULL REFERENCES locator_slips(id) ON DELETE CASCADE,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  reviewer_id UUID REFERENCES users(id) ON DELETE SET NULL,
  reviewer_name_snapshot TEXT NOT NULL,
  reviewer_role TEXT NOT NULL CHECK (reviewer_role IN ('primary', 'backup')),
  backup_rank INT CHECK (backup_rank IS NULL OR backup_rank > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_locator_reviewer_rank CHECK (
    (reviewer_role = 'primary' AND backup_rank IS NULL)
    OR (reviewer_role = 'backup' AND backup_rank IS NOT NULL)
  ),
  UNIQUE (locator_slip_id, reviewer_id)
);

CREATE INDEX IF NOT EXISTS idx_locator_slip_department_reviewers_user
  ON locator_slip_department_reviewers(reviewer_id, locator_slip_id);

-- =========================================
-- LOCATOR WORKFLOW HISTORY (APPEND-ONLY)
-- =========================================
CREATE TABLE IF NOT EXISTS locator_slip_history (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  locator_slip_id UUID NOT NULL REFERENCES locator_slips(id) ON DELETE RESTRICT,
  action TEXT NOT NULL CHECK (char_length(btrim(action)) > 0),
  from_status TEXT,
  to_status TEXT,
  actor_id UUID,
  actor_name_snapshot TEXT,
  actor_role TEXT,
  remarks TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_locator_slip_history_request_time
  ON locator_slip_history(locator_slip_id, created_at, id);

CREATE OR REPLACE FUNCTION prevent_locator_slip_history_mutation()
RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'locator_slip_history is append-only';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_prevent_locator_slip_history_mutation
  ON locator_slip_history;
CREATE TRIGGER trg_prevent_locator_slip_history_mutation
BEFORE UPDATE OR DELETE ON locator_slip_history
FOR EACH ROW EXECUTE FUNCTION prevent_locator_slip_history_mutation();

-- =========================================
