-- =========================================
-- BIOMETRIC ATTENDANCE LOGS (raw import from .dat files)
-- =========================================
CREATE TABLE IF NOT EXISTS biometric_attendance_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_ref_id UUID REFERENCES biometric_devices(id) ON DELETE RESTRICT,
  biometric_user_id TEXT NOT NULL,
  logged_at TIMESTAMPTZ NOT NULL,
  verify_code TEXT,
  punch_code TEXT,
  work_code TEXT,
  raw_line TEXT NOT NULL,
  source_file_name TEXT,
  imported_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT uq_biometric_attendance_logs_user_time UNIQUE (biometric_user_id, logged_at)
);

-- =========================================
-- RAW DTR LOGS
-- =========================================
CREATE TABLE IF NOT EXISTS dtr_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_ref_id UUID REFERENCES biometric_devices(id) ON DELETE SET NULL,

  local_uuid TEXT UNIQUE,
  biometric_user_id TEXT,

  log_time TIMESTAMPTZ NOT NULL,

  log_type TEXT NOT NULL
    CHECK (log_type IN ('time_in', 'time_out', 'break_in', 'break_out')),

  source TEXT NOT NULL DEFAULT 'biometric'
    CHECK (source IN ('biometric', 'manual', 'mobile', 'import')),

  sync_status TEXT NOT NULL DEFAULT 'synced'
    CHECK (sync_status IN ('pending', 'synced', 'failed')),

  remarks TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =========================================
-- DAILY DTR SUMMARY
-- =========================================
-- Exact punch exclusions retained by the Super Admin attendance reset tool.
CREATE TABLE IF NOT EXISTS attendance_reset_punches (
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  logged_at TIMESTAMPTZ NOT NULL,
  reset_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (employee_id, logged_at)
);

CREATE TABLE IF NOT EXISTS dtr_daily_summary (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  attendance_date DATE NOT NULL,

  assignment_id UUID REFERENCES assignments(id) ON DELETE SET NULL,
  shift_id UUID REFERENCES shifts(id) ON DELETE SET NULL,
  attendance_policy_id UUID REFERENCES attendance_policies(id) ON DELETE RESTRICT,
  holiday_id UUID REFERENCES holidays(id) ON DELETE SET NULL,
  leave_request_id UUID REFERENCES leave_requests(id) ON DELETE SET NULL,

  time_in TIMESTAMPTZ,
  time_out TIMESTAMPTZ,
  break_in TIMESTAMPTZ,
  break_out TIMESTAMPTZ,

  late_minutes INT NOT NULL DEFAULT 0 CHECK (late_minutes >= 0),
  undertime_minutes INT NOT NULL DEFAULT 0 CHECK (undertime_minutes >= 0),
  overtime_minutes INT NOT NULL DEFAULT 0 CHECK (overtime_minutes >= 0),
  total_hours NUMERIC(6,2) NOT NULL DEFAULT 0 CHECK (total_hours >= 0),
  shift_snapshot JSONB,

  status TEXT NOT NULL DEFAULT 'incomplete'
    CHECK (status IN (
      'present',
      'late',
      'absent',
      'on_leave',
      'holiday',
      'rest_day',
      'incomplete'
    )),
  pm_status TEXT CHECK (pm_status IS NULL OR pm_status IN ('present', 'late')),

  source TEXT NOT NULL DEFAULT 'system'
    CHECK (source IN ('system', 'manual', 'adjusted')),

  remarks TEXT,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT uq_dtr_daily_summary_employee_date UNIQUE (employee_id, attendance_date)
);

CREATE OR REPLACE FUNCTION queue_completed_month_dtr_reconciliation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  affected_employee UUID;
  affected_date DATE;
  operation_reason TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    affected_employee := OLD.employee_id;
    affected_date := OLD.attendance_date;
  ELSE
    affected_employee := NEW.employee_id;
    affected_date := NEW.attendance_date;
  END IF;
  operation_reason := 'dtr_' || lower(TG_OP);

  IF affected_date <
     date_trunc('month', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Manila')::date THEN
    INSERT INTO dtr_month_end_reconciliation_queue (
      employee_id, service_month, status, reason, metadata_json,
      required_at, reconciled_at, updated_at
    ) VALUES (
      affected_employee,
      date_trunc('month', affected_date)::date,
      'pending',
      operation_reason,
      jsonb_build_object('attendance_date', affected_date, 'operation', TG_OP),
      now(), NULL, now()
    )
    ON CONFLICT (employee_id, service_month) DO UPDATE
      SET status = 'pending',
          reason = EXCLUDED.reason,
          metadata_json = EXCLUDED.metadata_json,
          required_at = now(),
          last_error = NULL,
          reconciled_at = NULL,
          updated_at = now();
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF (OLD.employee_id, OLD.attendance_date)
       IS DISTINCT FROM (NEW.employee_id, NEW.attendance_date)
       AND OLD.attendance_date <
           date_trunc('month', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Manila')::date THEN
      INSERT INTO dtr_month_end_reconciliation_queue (
        employee_id, service_month, status, reason, metadata_json,
        required_at, reconciled_at, updated_at
      ) VALUES (
        OLD.employee_id,
        date_trunc('month', OLD.attendance_date)::date,
        'pending',
        operation_reason,
        jsonb_build_object('attendance_date', OLD.attendance_date, 'operation', TG_OP),
        now(), NULL, now()
      )
      ON CONFLICT (employee_id, service_month) DO UPDATE
        SET status = 'pending',
            reason = EXCLUDED.reason,
            metadata_json = EXCLUDED.metadata_json,
            required_at = now(),
            last_error = NULL,
            reconciled_at = NULL,
            updated_at = now();
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_queue_completed_month_dtr_reconciliation
  ON dtr_daily_summary;

CREATE TRIGGER trg_queue_completed_month_dtr_reconciliation
AFTER INSERT OR UPDATE OR DELETE ON dtr_daily_summary
FOR EACH ROW
EXECUTE FUNCTION queue_completed_month_dtr_reconciliation();

-- Deleting a processed DTR entry must not destroy its raw biometric evidence.
-- These immutable snapshots also suppress automatic recreation for the same day.
CREATE TABLE IF NOT EXISTS dtr_daily_summary_deletions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  deleted_dtr_summary_id UUID NOT NULL,
  employee_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  attendance_date DATE NOT NULL,
  source TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (btrim(reason) <> ''),
  deleted_by UUID REFERENCES users(id) ON DELETE SET NULL,
  record_snapshot JSONB NOT NULL,
  deleted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  restored_by UUID REFERENCES users(id) ON DELETE SET NULL,
  restoration_reason TEXT CHECK (
    restoration_reason IS NULL OR btrim(restoration_reason) <> ''
  ),
  restored_at TIMESTAMPTZ
);

