  appointment_status TEXT NOT NULL DEFAULT 'none',
  appointment_notes TEXT,
  no_show_count INT NOT NULL DEFAULT 0,
  meeting_request_status TEXT NOT NULL DEFAULT 'none'
    CHECK (meeting_request_status IN ('none', 'submitted', 'approved', 'reschedule_requested', 'declined')),
  meeting_proposed_at TIMESTAMPTZ,
  meeting_purpose TEXT,
  meeting_decision TEXT
    CHECK (meeting_decision IS NULL OR meeting_decision IN ('approved', 'declined', 'reschedule_requested')),
  meeting_decided_at TIMESTAMPTZ,
  meeting_decided_by UUID REFERENCES users(id) ON DELETE SET NULL,
  meeting_decision_remarks TEXT,
  meeting_reschedule_proposed_at TIMESTAMPTZ,
  is_test BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_mayor_endorsement_requests_reference_number
  ON mayor_endorsement_requests (reference_number)
  WHERE reference_number IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_mayor_endorsement_requests_application_id_legacy
  ON mayor_endorsement_requests (application_id)
  WHERE application_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS mayor_endorsement_activity_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  request_id UUID NOT NULL REFERENCES mayor_endorsement_requests(id) ON DELETE CASCADE,
  application_id UUID,
  actor_id UUID REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  remarks TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO recruitment_exam_time_limits (exam_type, time_limit_seconds)
VALUES
  ('bei', 0),
  ('general', 2700),
  ('math', 2700),
  ('general_info', 600)
ON CONFLICT (exam_type) DO NOTHING;

-- One exam result row per application (idempotent for existing DBs).
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'uq_recruitment_exam_results_application'
  ) THEN
    ALTER TABLE recruitment_exam_results
      ADD CONSTRAINT uq_recruitment_exam_results_application
      UNIQUE (application_id);
  END IF;
END $$;

-- =========================================
-- DOCUTRACKER
-- =========================================
-- Deploy source of truth for new environments: run this init-schema.sql only.
-- backend/scripts/migrations/docutracker/migrate-*.sql are for upgrading older DBs.
-- =========================================
CREATE TABLE IF NOT EXISTS docutracker_roles (
  role_id TEXT PRIMARY KEY,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO docutracker_roles(role_id)
VALUES ('admin'), ('hr'), ('supervisor'), ('employee')
ON CONFLICT (role_id) DO NOTHING;

CREATE TABLE IF NOT EXISTS docutracker_role_aliases (
  alias TEXT PRIMARY KEY,
  role_id TEXT NOT NULL REFERENCES docutracker_roles(role_id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO docutracker_role_aliases(alias, role_id)
VALUES ('hr_staff', 'hr'), ('dept_head', 'supervisor')
ON CONFLICT (alias) DO NOTHING;

CREATE TABLE IF NOT EXISTS docutracker_documents (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_number TEXT NOT NULL UNIQUE,
  document_type TEXT NOT NULL DEFAULT 'memo',
  title TEXT NOT NULL,
  description TEXT,
  source_module TEXT,
  source_table TEXT,
  source_record_id UUID,
  source_title TEXT,
  file_path TEXT,
  file_name TEXT,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  originating_department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  current_holder_id UUID REFERENCES users(id) ON DELETE SET NULL,
  current_step INT DEFAULT 1,
  workflow_version INT,
  status TEXT NOT NULL DEFAULT 'pending',
  sent_time TIMESTAMPTZ,
  deadline_time TIMESTAMPTZ,
  reviewed_time TIMESTAMPTZ,
  escalation_level INT NOT NULL DEFAULT 0,
  needs_admin_intervention BOOLEAN DEFAULT false,
  priority TEXT NOT NULL DEFAULT 'normal',
  confidentiality_level TEXT NOT NULL DEFAULT 'internal',
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  submitted_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  cancelled_at TIMESTAMPTZ,
  archived_at TIMESTAMPTZ,
  deleted_at TIMESTAMPTZ,
  release_required BOOLEAN NOT NULL DEFAULT false,
  released_to_department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  released_to_department_name TEXT,
  released_by UUID REFERENCES users(id) ON DELETE SET NULL,
  released_by_name TEXT,
  released_at TIMESTAMPTZ,
  release_remarks TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_documents_release_native_check_v1
    CHECK (NOT release_required OR source_module IS NULL),
  CONSTRAINT docutracker_documents_release_state_check_v1
    CHECK (
      released_at IS NULL
      OR (
        release_required
        AND btrim(COALESCE(released_to_department_name, '')) <> ''
      )
    ),
  CONSTRAINT docutracker_documents_priority_check_v1
    CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  CONSTRAINT docutracker_documents_confidentiality_check_v1
    CHECK (confidentiality_level IN ('public', 'internal', 'confidential', 'restricted')),
  CONSTRAINT docutracker_documents_metadata_object_check_v1
    CHECK (jsonb_typeof(metadata) = 'object'),
  CONSTRAINT docutracker_documents_status_check_prod_v2
    CHECK (status IN (
      'pending', 'in_review', 'approved', 'rejected', 'returned',
      'overdue', 'escalated', 'cancelled'
    )),
  CONSTRAINT docutracker_documents_current_step_check_prod_v1
    CHECK (current_step IS NULL OR current_step >= 1),
  CONSTRAINT docutracker_documents_escalation_level_check_prod_v1
    CHECK (escalation_level >= 0)
);

CREATE TABLE IF NOT EXISTS docutracker_routing_configs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_type TEXT NOT NULL UNIQUE,
  steps JSONB NOT NULL DEFAULT '[]',
  review_deadline_hours INT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_routing_configs_steps_is_array_check_prod_v1
    CHECK (jsonb_typeof(steps) = 'array'),
  CONSTRAINT docutracker_routing_configs_review_deadline_hours_check_prod_v1
    CHECK (review_deadline_hours > 0),
  CONSTRAINT docutracker_routing_configs_review_deadline_hours_check CHECK ((review_deadline_hours > 0))
);

CREATE TABLE IF NOT EXISTS docutracker_routing_config_versions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  shared_workflow_id UUID REFERENCES approval_workflows(id),
  shared_workflow_version INTEGER,
  document_type TEXT NOT NULL,
  version INT NOT NULL,
  steps JSONB NOT NULL,
  review_deadline_hours INT NOT NULL DEFAULT 1,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (document_type, version)
);

CREATE TABLE IF NOT EXISTS docutracker_workflow_steps (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_type TEXT NOT NULL,
  workflow_version INT NOT NULL DEFAULT 1,
  step_order INT NOT NULL CHECK (step_order > 0),
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  assignee_source TEXT NOT NULL DEFAULT 'specific_users'
    CHECK (assignee_source IN (
      'specific_users',
      'department_reviewers',
      'submitter_department_reviewers',
      'final_hr_reviewers',
      'active_mayor'
    )),
  label TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (document_type, workflow_version, step_order)
);

CREATE TABLE IF NOT EXISTS docutracker_workflow_step_assignees (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  step_id UUID NOT NULL REFERENCES docutracker_workflow_steps(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  is_primary BOOLEAN NOT NULL DEFAULT false,
  backup_rank INT NULL CHECK (backup_rank IS NULL OR backup_rank > 0),
  is_enabled BOOLEAN NOT NULL DEFAULT true,
  allowed_actions TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (step_id, user_id),
  CHECK (NOT is_primary OR backup_rank IS NULL),
  CHECK (is_primary OR backup_rank IS NOT NULL),
  UNIQUE (step_id, backup_rank),
  CHECK (allowed_actions <@ ARRAY['approve','forward','reject','return']::TEXT[])
);

CREATE TABLE IF NOT EXISTS docutracker_document_history (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  action TEXT,
  actor_id UUID REFERENCES users(id) ON DELETE SET NULL,
  actor_name TEXT,
  from_step INT,
  to_step INT,
  from_status TEXT,
  to_status TEXT,
  remarks TEXT,
  is_overdue_log BOOLEAN DEFAULT false,
  is_escalation_log BOOLEAN DEFAULT false,
  escalation_level INT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_docutracker_history_action
    CHECK (action IS NULL OR action IN (
      'created', 'submitted', 'forwarded', 'approved', 'rejected', 'returned',
      'metadata_updated', 'remark', 'escalated', 'overdue', 'assigned', 'signed',
      'released'
    ))
);

CREATE TABLE IF NOT EXISTS docutracker_routing_records (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  step_order INT NOT NULL,
  assignee_id UUID REFERENCES users(id) ON DELETE SET NULL,
  sent_time TIMESTAMPTZ,
  deadline_time TIMESTAMPTZ,
  reviewed_time TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'pending',
  remarks TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_routing_records_status_check_prod_v2
    CHECK (status IN (
      'pending', 'in_review', 'approved', 'rejected', 'returned',
      'overdue', 'escalated', 'cancelled'
    )),
  CONSTRAINT docutracker_routing_records_step_order_check_prod_v1
    CHECK (step_order >= 1)
);

CREATE TABLE IF NOT EXISTS docutracker_routing_record_assignees (
  routing_record_id UUID NOT NULL REFERENCES docutracker_routing_records(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (routing_record_id, user_id)
);

CREATE TABLE IF NOT EXISTS docutracker_notifications (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  title TEXT,
  body TEXT,
  read BOOLEAN DEFAULT false,
  event_key TEXT,
  channel TEXT NOT NULL DEFAULT 'in_app',
  delivery_status TEXT NOT NULL DEFAULT 'sent',
  read_at TIMESTAMPTZ,
  sent_at TIMESTAMPTZ,
  failed_at TIMESTAMPTZ,
  failure_reason TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_notifications_type_check
    CHECK (type IN (
      'assigned', 'deadline_near', 'overdue', 'escalated', 'returned', 'rejected',
      'released'
    )),
  CONSTRAINT docutracker_notifications_channel_check_v1
    CHECK (channel IN ('in_app', 'email', 'sms', 'push')),
  CONSTRAINT docutracker_notifications_delivery_status_check_v1
    CHECK (delivery_status IN ('pending', 'sent', 'delivered', 'failed', 'cancelled'))
);

CREATE TABLE IF NOT EXISTS docutracker_permissions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  role_id TEXT REFERENCES docutracker_roles(role_id) ON DELETE CASCADE,
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  document_type TEXT NOT NULL DEFAULT '*',
  action TEXT NOT NULL,
  granted BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_permissions_scope_check_v1
    CHECK ((user_id IS NOT NULL) <> (role_id IS NOT NULL)),
  CONSTRAINT docutracker_permissions_action_check_prod_v1
    CHECK (action IN (
      'view', 'create', 'create_draft', 'submit', 'download', 'edit', 'delete',
      'forward', 'approve', 'reject', 'return', 'release'
    )),
  CONSTRAINT docutracker_permissions_role_fk_prod_v1 FOREIGN KEY (role_id) REFERENCES docutracker_roles(role_id) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT docutracker_permissions_scope_check_prod_v2 CHECK (((user_id IS NOT NULL) <> (role_id IS NOT NULL)))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_docutracker_permissions_unique ON public.docutracker_permissions USING btree (user_id, document_type, action) WHERE (user_id IS NOT NULL);

CREATE TABLE IF NOT EXISTS docutracker_escalation_configs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_type TEXT NOT NULL,
  department_id UUID REFERENCES departments(id) ON DELETE SET NULL,
  escalation_target_role TEXT,
  escalation_delay_minutes INT NOT NULL DEFAULT 60,
  max_escalation_level INT NOT NULL DEFAULT 3,
  notify_original_sender BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_escalation_configs_escalation_delay_minutes_check
    CHECK (escalation_delay_minutes > 0),
  CONSTRAINT docutracker_escalation_configs_max_escalation_level_check
    CHECK (max_escalation_level >= 1),
  CONSTRAINT docutracker_escalation_configs_escalation_delay_minutes_check_p CHECK ((escalation_delay_minutes > 0)),
  CONSTRAINT docutracker_escalation_configs_max_escalation_level_check_prod_ CHECK ((max_escalation_level >= 1))
);

CREATE TABLE IF NOT EXISTS docutracker_document_contents (
  document_id UUID PRIMARY KEY REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  format_version INT NOT NULL DEFAULT 1 CHECK (format_version > 0),
  pages JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(pages) = 'array'),
  page_size TEXT NOT NULL DEFAULT 'A4' CHECK (page_size = 'A4'),
  margins JSONB NOT NULL DEFAULT
    '{"top":0.08,"right":0.08,"bottom":0.08,"left":0.08}'::jsonb
    CHECK (jsonb_typeof(margins) = 'object'),
  revision INT NOT NULL DEFAULT 1 CHECK (revision > 0),
  updated_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS docutracker_signature_assets (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  owner_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  image_bytes BYTEA NOT NULL CHECK (octet_length(image_bytes) BETWEEN 1 AND 2097152),
  mime_type TEXT NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg')),
  source_type TEXT NOT NULL CHECK (source_type IN ('drawn', 'uploaded')),
  display_name TEXT,
  is_saved BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS docutracker_signature_fields (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  page_number INT NOT NULL CHECK (page_number > 0),
  position_x DOUBLE PRECISION NOT NULL CHECK (position_x >= 0 AND position_x <= 1),
  position_y DOUBLE PRECISION NOT NULL CHECK (position_y >= 0 AND position_y <= 1),
  width DOUBLE PRECISION NOT NULL CHECK (width > 0 AND width <= 1 AND position_x + width <= 1),
  height DOUBLE PRECISION NOT NULL CHECK (height > 0 AND height <= 1 AND position_y + height <= 1),
  assigned_signer_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  label TEXT NOT NULL DEFAULT 'Sign Here' CHECK (length(btrim(label)) BETWEEN 1 AND 80),
  signature_asset_id UUID REFERENCES docutracker_signature_assets(id) ON DELETE RESTRICT,
  signed_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  signer_name_snapshot TEXT,
  -- Printed identity frozen at signing; NULL on fields signed before it existed.
  signer_position_snapshot TEXT,
  signer_role_snapshot TEXT,
  signed_at TIMESTAMPTZ,
  locked_at TIMESTAMPTZ,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (
    (signature_asset_id IS NULL AND signed_by IS NULL AND signed_at IS NULL
      AND locked_at IS NULL AND signer_name_snapshot IS NULL)
    OR
    (signature_asset_id IS NOT NULL AND signed_by IS NOT NULL AND signed_at IS NOT NULL
      AND locked_at IS NOT NULL AND signer_name_snapshot IS NOT NULL)
  ),
  CONSTRAINT docutracker_signature_fields_identity_snapshot_check_v1 CHECK (
    (signer_position_snapshot IS NULL OR btrim(signer_position_snapshot) <> '')
    AND (signer_role_snapshot IS NULL OR btrim(signer_role_snapshot) <> '')
    AND (signed_at IS NOT NULL
      OR (signer_position_snapshot IS NULL AND signer_role_snapshot IS NULL))
  )
);

-- Linked DTR leave e-signatures (final slots: applicant / dept head / HR).
CREATE TABLE IF NOT EXISTS docutracker_leave_signatures (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  leave_request_id UUID NOT NULL
    REFERENCES leave_requests(id) ON DELETE CASCADE,
  slot_key TEXT NOT NULL,
  assigned_signer_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  signature_asset_id UUID NOT NULL
    REFERENCES docutracker_signature_assets(id) ON DELETE RESTRICT,
  signed_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  signer_name_snapshot TEXT NOT NULL,
  signed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_leave_signatures_slot_check
    CHECK (slot_key IN ('applicant', 'department_head', 'hr_approver')),
  CONSTRAINT docutracker_leave_signatures_signer_check
    CHECK (assigned_signer_id = signed_by),
  CONSTRAINT docutracker_leave_signatures_name_check
    CHECK (length(btrim(signer_name_snapshot)) BETWEEN 1 AND 200),
  CONSTRAINT docutracker_leave_signatures_request_revision_slot_unique
    UNIQUE (leave_request_id, revision, slot_key)
);

CREATE INDEX IF NOT EXISTS idx_docutracker_leave_signatures_signer
  ON docutracker_leave_signatures(assigned_signer_id, leave_request_id);

CREATE TABLE IF NOT EXISTS docutracker_rsp_source_signatures (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  source_table TEXT NOT NULL CONSTRAINT docutracker_rsp_source_signatures_source_check CHECK (source_table IN (
    'applicants_profile_entries', 'selection_lineup_entries',
    'computation_of_points_entries', 'work_experience_sheet_entries',
    'turn_around_time_entries', 'idp_entries',
    'action_brainstorming_coaching_entries'
  )),
  source_record_id UUID NOT NULL,
  slot_key TEXT NOT NULL CONSTRAINT docutracker_rsp_source_signatures_slot_check CHECK (slot_key IN (
    'prepared_by', 'checked_by', 'applicant', 'noted_by',
    'reviewed_by', 'approved_by', 'certified_by'
  )),
  label TEXT NOT NULL,
  assigned_signer_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  assignment_source TEXT NOT NULL DEFAULT 'manual' CHECK (
    assignment_source IN ('creator', 'automatic', 'admin_recovery', 'manual')
  ),
  recovery_remarks TEXT CHECK (
    recovery_remarks IS NULL
    OR length(btrim(recovery_remarks)) BETWEEN 5 AND 500
  ),
  signature_asset_id UUID REFERENCES docutracker_signature_assets(id) ON DELETE RESTRICT,
  signed_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  signer_name_snapshot TEXT,
  signed_at TIMESTAMPTZ,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (
    (signature_asset_id IS NULL AND signed_by IS NULL
      AND signer_name_snapshot IS NULL AND signed_at IS NULL)
    OR
    (signature_asset_id IS NOT NULL AND signed_by = assigned_signer_id
      AND length(btrim(signer_name_snapshot)) BETWEEN 1 AND 200
      AND signed_at IS NOT NULL)
  ),
  UNIQUE (source_table, source_record_id, slot_key)
);

CREATE TABLE IF NOT EXISTS docutracker_transition_requests (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES docutracker_documents(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  actor_id UUID REFERENCES users(id) ON DELETE SET NULL,
  response_payload JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (document_id, action, idempotency_key)
);

-- Locator signatures are request-bound. The stored revision prevents an
-- e-signature from being reused after the underlying slip is corrected.
CREATE TABLE IF NOT EXISTS docutracker_locator_signatures (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  locator_slip_id UUID NOT NULL REFERENCES locator_slips(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL,
  slot_key TEXT NOT NULL CHECK (slot_key IN ('applicant', 'department_head', 'hr_approver')),
  signature_asset_id UUID NOT NULL REFERENCES docutracker_signature_assets(id) ON DELETE RESTRICT,
  signed_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  signer_name_snapshot TEXT NOT NULL,
  signed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (locator_slip_id, revision, slot_key)
);

CREATE OR REPLACE FUNCTION invalidate_locator_signatures() RETURNS trigger AS $$
BEGIN
  IF ROW(NEW.slip_date, NEW.office, NEW.reason, NEW.request_type,
         NEW.am_in, NEW.am_out, NEW.pm_in, NEW.pm_out, NEW.employee_id,
         NEW.department_id, NEW.attachment_path, NEW.attachment_uploaded_at)
     IS DISTINCT FROM
     ROW(OLD.slip_date, OLD.office, OLD.reason, OLD.request_type,
         OLD.am_in, OLD.am_out, OLD.pm_in, OLD.pm_out, OLD.employee_id,
         OLD.department_id, OLD.attachment_path, OLD.attachment_uploaded_at)
     OR (NEW.status IS DISTINCT FROM OLD.status AND
         NEW.status IN ('returned_for_correction', 'returned', 'cancelled', 'revoked'))
  THEN
    NEW.signature_revision := OLD.signature_revision + 1;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS locator_signature_revision ON locator_slips;
CREATE TRIGGER locator_signature_revision BEFORE UPDATE ON locator_slips
FOR EACH ROW EXECUTE FUNCTION invalidate_locator_signatures();

CREATE TABLE IF NOT EXISTS docutracker_document_number_seq (
  year INT PRIMARY KEY,
  last_value BIGINT NOT NULL DEFAULT 0
);

-- DocuTracker indexes
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_created_by ON docutracker_documents(created_by);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_originating_department
  ON docutracker_documents(originating_department_id)
  WHERE originating_department_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_current_holder ON docutracker_documents(current_holder_id);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_status ON docutracker_documents(status);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_doc_type ON docutracker_documents(document_type);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_type_status_created
  ON docutracker_documents(document_type, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_holder_status_deadline
  ON docutracker_documents(current_holder_id, status, deadline_time);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_deadline_active
  ON docutracker_documents(deadline_time)
  WHERE status IN ('pending', 'in_review', 'escalated', 'overdue');
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_priority_status
  ON docutracker_documents(priority, status, created_at DESC)
  WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_source_record
  ON docutracker_documents(source_module, source_table, source_record_id)
  WHERE source_record_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_metadata_gin
  ON docutracker_documents USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_docutracker_documents_released_to_department
  ON docutracker_documents(released_to_department_id, released_at DESC)
  WHERE released_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS docutracker_document_types (
  document_type TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  description TEXT,
  number_prefix TEXT,
  default_priority TEXT NOT NULL DEFAULT 'normal',
  is_enabled BOOLEAN NOT NULL DEFAULT true,
  -- Approved documents of this type wait for an authorized release to a department.
  requires_release BOOLEAN NOT NULL DEFAULT false,
  print_template_version_id UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_document_types_type_not_blank
    CHECK (btrim(document_type) <> ''),
  CONSTRAINT docutracker_document_types_display_name_not_blank
    CHECK (btrim(display_name) <> ''),
  CONSTRAINT docutracker_document_types_priority_check
    CHECK (default_priority IN ('low', 'normal', 'high', 'urgent'))
);

INSERT INTO docutracker_document_types (document_type, display_name, description, number_prefix, requires_release)
VALUES
  ('memo', 'Memo', 'Internal memorandum document', 'MEMO', true),
  ('purchaseRequest', 'Purchase Request', 'Purchase request document', 'PR', false)
ON CONFLICT (document_type) DO NOTHING;

CREATE TABLE IF NOT EXISTS docutracker_print_template_versions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_type TEXT NOT NULL
    REFERENCES docutracker_document_types(document_type) ON DELETE CASCADE,
  background_pdf BYTEA,
  background_name TEXT,
  print_layout JSONB,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_print_template_versions_layout_object_check
    CHECK (print_layout IS NULL OR jsonb_typeof(print_layout) = 'object')
);

CREATE INDEX IF NOT EXISTS idx_docutracker_print_template_versions_type
  ON docutracker_print_template_versions (document_type, created_at DESC);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'docutracker_document_types_print_template_version_fkey'
  ) THEN
    ALTER TABLE docutracker_document_types
      ADD CONSTRAINT docutracker_document_types_print_template_version_fkey
      FOREIGN KEY (print_template_version_id)
      REFERENCES docutracker_print_template_versions(id)
      ON DELETE SET NULL;
  END IF;
END $$;

-- Default memorandum letterhead (HR A4 header and footer).
-- Default memorandum letterhead: HR A4 header and footer.
-- print_layout stays empty, so Memo and Purchase Request keep their built-in text.
-- Re-running refreshes this seeded artwork and leaves a replaced letterhead alone.

CREATE TABLE IF NOT EXISTS docutracker_letterheads (
  document_type TEXT PRIMARY KEY
    REFERENCES docutracker_document_types(document_type) ON DELETE CASCADE,
  background_pdf BYTEA NOT NULL,
  letterhead_png BYTEA NOT NULL,
  source_name TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT docutracker_letterheads_source_name_not_blank
    CHECK (btrim(source_name) <> ''),
  CONSTRAINT docutracker_letterheads_pdf_not_empty
    CHECK (octet_length(background_pdf) > 0),
  CONSTRAINT docutracker_letterheads_png_not_empty
    CHECK (octet_length(letterhead_png) > 0)
);

